import { useState } from "react";
type Todo = { id: number; text: string; done: boolean };
export default function TodoApp() { const [todos, setTodos] = useState<Todo[]>([]); const add = () => setTodos((items) => [...items, { id: Date.now(), text: "React 학습", done: false }]); return <><button onClick={add}>추가</button>{todos.map((todo) => <label key={todo.id}><input type="checkbox" checked={todo.done} onChange={() => setTodos((items) => items.map((item) => item.id === todo.id ? { ...item, done: !item.done } : item))} />{todo.text}</label>)}</>; }

