practice.solutionCode:
import { useReducer } from "react";
type Action = { type: "increase" } | { type: "reset" };
function reducer(count: number, action: Action) { return action.type === "increase" ? count + 1 : 0; }
export default function Counter() { const [count, dispatch] = useReducer(reducer, 0); return <><button onClick={() => dispatch({ type: "increase" })}>{count}</button><button onClick={() => dispatch({ type: "reset" })}>초기화</button></>; }

