import React from "react";
class ErrorBoundary extends React.Component<React.PropsWithChildren, { failed: boolean }> { state = { failed: false }; static getDerivedStateFromError() { return { failed: true }; } render() { return this.state.failed ? <p>문제가 발생했습니다.</p> : this.props.children; } }
export default ErrorBoundary;

