import { QueryClient, QueryClientProvider, useMutation, useQueryClient } from "@tanstack/react-query";
const client = new QueryClient();
function AddStudy() { const queryClient = useQueryClient(); const mutation = useMutation({ mutationFn: async (title: string) => ({ id: Date.now(), title }), onSuccess: () => queryClient.invalidateQueries({ queryKey: ["studies"] }) }); return <button onClick={() => mutation.mutate("React")}>{mutation.isPending ? "추가 중" : mutation.data?.title ?? "추가"}</button>; }
export default function App() { return <QueryClientProvider client={client}><AddStudy /></QueryClientProvider>; }

