import { QueryClient, QueryClientProvider, useMutation, useQueryClient } from "@tanstack/react-query";
const client = new QueryClient(); client.setQueryData(["studies"], [{ id: 1, title: "React", done: false }]);
function Complete({ id = 1 }: { id?: number }) { const queryClient = useQueryClient(); const mutation = useMutation({ mutationFn: async () => ({ ok: true }), onMutate: async () => { const previous = queryClient.getQueryData(["studies"]); queryClient.setQueryData<any[]>(["studies"], (items = []) => items.map((item) => item.id === id ? { ...item, done: true } : item)); return { previous }; }, onError: (_e, _v, context) => queryClient.setQueryData(["studies"], context?.previous) }); return <button onClick={() => mutation.mutate()}>낙관적으로 완료</button>; }
export default function App() { return <QueryClientProvider client={client}><Complete /></QueryClientProvider>; }

